AUGUST_4_SLUG = "pokemon-tcg-ai-battle-episodes-2026-08-04"
SOURCE_PREFIX = "kptcg-e01-majkel-corpus-review-source-v1/"
TRAINING_REQUEST_PATH = "configs/e01_production_recurrent_bc_request_v2.json"
TRAINING_REQUEST_SHA256 = "297679d5a1a2ca43b3f8ef1dc158cdc82fc68e8c5fe7b6791d790bded586ea0d"
RUNNER_PATH = "scripts/e01_production_recurrent_bc_v2.py"
RUNNER_SHA256 = "92e2eeab5986d21e648b8db64ee19a85ffadb60904351863af528d48c4c94413"
IMPLEMENTATION_PATH = "src/ptcg_rl/g3/bc_production_v2.py"
