RETAINED_FILES = 58
RETAINED_BYTES = 341_559_745
RETAINED_INVENTORY_SHA256 = "d03105906d9e066045410bc4da07ec7bd045f5b1285d35ddc516c1e7960b5c43"
AUGUST_3_FILES = 4_721
AUGUST_3_BYTES = 21_451_850_075
AUGUST_4_FILES = 4_812
AUGUST_4_BYTES = 21_457_813_826
SELECTED_REPLAY_FILES = 316
SELECTED_REPLAY_BYTES = 1_327_994_902
MAXIMUM_EPOCHS = 4
MAXIMUM_OPTIMIZER_STEPS = 844
