REQUEST_BYTES = base64.b64decode("")
VERIFIER_BYTES = base64.b64decode("")
SOURCE_BUNDLE_RECORDS = json.loads(zlib.decompress(base64.b64decode("")))
SELECTED_REPLAY_RECORDS = json.loads(zlib.decompress(base64.b64decode("")))


class NotebookContractError(RuntimeError):
    pass


def sha256_bytes(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def sha256_file(path: Path) -> str:
    return sha256_bytes(path.read_bytes())


def canonical_inventory_hash(records: Sequence[Mapping[str, Any]]) -> str:
    payload = [
        {"name": str(item["name"]), "bytes": int(item["bytes"])}
        for item in sorted(records, key=lambda item: str(item["name"]))
    ]
    raw = (json.dumps(payload, sort_keys=True, separators=(",", ":")) + "\n").encode()
    return sha256_bytes(raw)


def inventory_records(root: Path) -> list[dict[str, Any]]:
    return [
        {"name": path.relative_to(root).as_posix(), "bytes": path.stat().st_size}
        for path in sorted(root.rglob("*"))
        if path.is_file()
    ]


def find_mount(input_root: Path, slug: str) -> Path:
    candidates = [
        input_root / slug,
        input_root / "datasets" / "ashok205" / slug,
        input_root / "datasets" / "organizations" / "kaggle" / slug,
        input_root / "datasets" / "kaggle" / slug,
    ]
    found = [path.resolve() for path in candidates if path.is_dir()]
    if len(found) == 1:
        return found[0]
    shallow: list[Path] = []
    if input_root.is_dir():
        for current, dirs, _files in os.walk(input_root):
            current_path = Path(current)
            depth = len(current_path.relative_to(input_root).parts)
            if depth >= 4:
                dirs[:] = []
            for name in list(dirs):
                if name == slug:
                    shallow.append((current_path / name).resolve())
    unique = sorted(set(found + shallow))
    if len(unique) != 1:
        raise NotebookContractError(f"expected exactly one Kaggle mount for {slug}, found {unique}")
    return unique[0]


def require_inventory(
    root: Path,
    *,
    expected_files: int,
    expected_bytes: int,
    expected_hash: str | None,
    label: str,
) -> list[dict[str, Any]]:
    records = inventory_records(root)
    total = sum(int(item["bytes"]) for item in records)
    if len(records) != expected_files or total != expected_bytes:
        raise NotebookContractError(
            f"{label} inventory aggregate differs: {len(records)} files/{total} bytes"
        )
    if expected_hash is not None and canonical_inventory_hash(records) != expected_hash:
        raise NotebookContractError(f"{label} inventory hash differs")
    return records


def require_exact_source_bundle(root: Path) -> None:
    records = require_inventory(
        root,
        expected_files=SOURCE_BUNDLE_FILES,
        expected_bytes=SOURCE_BUNDLE_BYTES,
        expected_hash=SOURCE_BUNDLE_INVENTORY_SHA256,
        label="source bundle",
    )
    expected = [
        {"name": str(item["name"]), "bytes": int(item["bytes"])}
        for item in SOURCE_BUNDLE_RECORDS
    ]
    if sorted(records, key=lambda item: item["name"]) != sorted(expected, key=lambda item: item["name"]):
        raise NotebookContractError("source-bundle path/size listing differs")


def materialize_source_tree(source_mount: Path, work_root: Path) -> None:
    if work_root.exists():
        raise NotebookContractError(f"working root already exists: {work_root}")
    work_root.mkdir(parents=True)
    ordered: list[tuple[int, str, str]] = []
    for item in SOURCE_BUNDLE_RECORDS:
        name = str(item["name"])
        if name.startswith(SOURCE_PREFIX):
            relative = name[len(SOURCE_PREFIX):]
            priority = 0
        else:
            relative = name
            priority = 1
        ordered.append((priority, name, relative))
    for _priority, source_name, relative in sorted(ordered):
        source = source_mount / source_name
        destination = work_root / relative
        if not source.is_file():
            raise NotebookContractError(f"source-bundle file missing: {source_name}")
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, destination)
    request = work_root / TRAINING_REQUEST_PATH
    request.parent.mkdir(parents=True, exist_ok=True)
    request.write_bytes(REQUEST_BYTES)
    verifier = work_root / VERIFIER_PATH
    verifier.parent.mkdir(parents=True, exist_ok=True)
    verifier.write_bytes(VERIFIER_BYTES)
    required = {
        TRAINING_REQUEST_PATH: TRAINING_REQUEST_SHA256,
        RUNNER_PATH: RUNNER_SHA256,
        IMPLEMENTATION_PATH: IMPLEMENTATION_SHA256,
        VERIFIER_PATH: VERIFIER_SHA256,
        "reports/artifacts/e01-approved-replay-corpus-manifest-v3.json": "c032694d3601d2570c8e2199c886e452af11f2d72b47379ad08761f16a6b3267",
        "private/assets/official/EN_Card_Data.csv": "a0ea63cf7adcb65d35436ce0eb390de6e2e35654a7c67c065a45f4abaa00f373",
    }
    for relative, expected in required.items():
        candidate = work_root / relative
        if not candidate.is_file() or sha256_file(candidate) != expected:
            raise NotebookContractError(f"materialized source identity differs: {relative}")
    checkpoint_dir = work_root / CHECKPOINT_DIRECTORY
    checkpoint_path = work_root / CHECKPOINT_PATH
    report_path = work_root / "reports/artifacts/e01-notebook-checkpoint-reconstruction-v1.json"
    subprocess.run(
        [
            sys.executable,
            str(verifier),
            "--input-dir",
            str(checkpoint_dir),
            "--output-zip",
            str(checkpoint_path),
            "--report",
            str(report_path),
        ],
        check=True,
        timeout=120,
    )
    if checkpoint_path.stat().st_size != CHECKPOINT_BYTES or sha256_file(checkpoint_path) != CHECKPOINT_SHA256:
        raise NotebookContractError("reconstructed checkpoint package differs")


def load_approval(path: Path, wrapper_sha256: str, notebook_request_sha256: str) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text())
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise NotebookContractError(f"cannot load approval receipt: {error}") from error
    if value.get("kind") != "E01_PRODUCTION_RECURRENT_BC_APPROVAL_V2" or value.get("approved_by") != "user":
        raise NotebookContractError("approval identity differs")
    exact = {
        "request_sha256": TRAINING_REQUEST_SHA256,
        "runner_sha256": RUNNER_SHA256,
        "wrapper_sha256": wrapper_sha256,
        "notebook_request_sha256": notebook_request_sha256,
    }
    for key, expected in exact.items():
        if value.get(key) != expected:
            raise NotebookContractError(f"approval {key} differs")
    authorization = value.get("authorization", {})
    for key in (
        "notebook_create",
        "notebook_save_and_run",
        "replay_body_read",
        "optimizer_steps",
        "training",
        "private_kaggle_cpu",
        "notebook_output_download",
    ):
        if authorization.get(key) is not True:
            raise NotebookContractError(f"approval does not authorize {key}")
    for key in (
        "agent_logs",
        "gpu",
        "tpu",
        "internet",
        "test_replay_read",
        "label_materialization",
        "model_promotion",
        "submission",
        "git_commit",
        "git_push",
    ):
        if authorization.get(key) is not False:
            raise NotebookContractError(f"approval expands forbidden field {key}")
    return value


def resolve_replay(root: Path, dataset_path: str) -> Path:
    direct = root / dataset_path
    nested = root / "episodes" / Path(dataset_path).name
    candidates = [path for path in (direct, nested) if path.is_file()]
    if len(candidates) != 1:
        raise NotebookContractError(f"expected one mounted replay for {dataset_path}")
    return candidates[0]


def verify_selected_replays(mounts: Mapping[str, Path]) -> None:
    if len(SELECTED_REPLAY_RECORDS) != SELECTED_REPLAY_FILES:
        raise NotebookContractError("embedded selected replay count differs")
    total = 0
    for item in SELECTED_REPLAY_RECORDS:
        path = resolve_replay(mounts[str(item["source"])], str(item["dataset_path"]))
        raw = path.read_bytes()
        total += len(raw)
        if len(raw) != int(item["bytes"]) or sha256_bytes(raw) != str(item["sha256"]):
            raise NotebookContractError(f"selected replay differs for episode {item['episode_id']}")
    if total != SELECTED_REPLAY_BYTES:
        raise NotebookContractError("selected replay byte total differs")


def output_inventory(root: Path) -> list[dict[str, Any]]:
    return [
        {
            "path": path.relative_to(root).as_posix(),
            "bytes": path.stat().st_size,
            "sha256": sha256_file(path),
        }
        for path in sorted(root.rglob("*"))
        if path.is_file()
    ]


def main() -> None:
    parser = argparse.ArgumentParser(description="Execute exact E01 production recurrent BC in one private Kaggle CPU notebook.")
    parser.add_argument("--input-root", type=Path, default=Path("/kaggle/input"))
    parser.add_argument("--working-root", type=Path, default=Path("/kaggle/working/kptcg-e01-production-bc-v2"))
    parser.add_argument("--approval-receipt", type=Path, required=True)
    parser.add_argument("--notebook-request-sha256", required=True)
    args = parser.parse_args()
    started = time.monotonic()
    wrapper_path = Path(__file__).resolve()
    wrapper_sha = sha256_file(wrapper_path)
    approval = load_approval(args.approval_receipt.resolve(), wrapper_sha, args.notebook_request_sha256)
    source_mount = find_mount(args.input_root, SOURCE_BUNDLE_SLUG)
    retained_mount = find_mount(args.input_root, RETAINED_SLUG)
    august_3_mount = find_mount(args.input_root, AUGUST_3_SLUG)
    august_4_mount = find_mount(args.input_root, AUGUST_4_SLUG)
    require_exact_source_bundle(source_mount)
    require_inventory(
        retained_mount,
        expected_files=RETAINED_FILES,
        expected_bytes=RETAINED_BYTES,
        expected_hash=RETAINED_INVENTORY_SHA256,
        label="retained dataset",
    )
    require_inventory(
        august_3_mount,
        expected_files=AUGUST_3_FILES,
        expected_bytes=AUGUST_3_BYTES,
        expected_hash=None,
        label="August 3 daily dataset",
    )
    require_inventory(
        august_4_mount,
        expected_files=AUGUST_4_FILES,
        expected_bytes=AUGUST_4_BYTES,
        expected_hash=None,
        label="August 4 daily dataset",
    )
    materialize_source_tree(source_mount, args.working_root)
    sys.path.insert(0, str(args.working_root / "src"))
    import torch
    if torch.cuda.is_available():
        raise NotebookContractError("GPU is visible in CPU-only training")
    mounts = {
        "retained_private": retained_mount,
        "august_3_daily": august_3_mount,
        "august_4_daily": august_4_mount,
    }
    verify_selected_replays(mounts)
    from ptcg_rl.g3.bc_production_v2 import execute_authorized_training
    output_dir = args.working_root / "outputs/e01-production-recurrent-bc-v1"
    elapsed = int(time.monotonic() - started)
    remaining = MAXIMUM_WALL_SECONDS - elapsed
    if remaining <= 0:
        raise NotebookContractError("preflight exhausted the wall-time cap")
    def timeout_handler(_signum: int, _frame: Any) -> None:
        raise TimeoutError("production BC exceeded the four-hour wall cap")
    signal.signal(signal.SIGALRM, timeout_handler)
    signal.alarm(remaining)
    try:
        report = execute_authorized_training(
            args.working_root,
            args.working_root / TRAINING_REQUEST_PATH,
            args.approval_receipt.resolve(),
            mounts,
            output_dir,
        )
    finally:
        signal.alarm(0)
    if int(report.get("optimizer_steps", -1)) > MAXIMUM_OPTIMIZER_STEPS:
        raise NotebookContractError("optimizer step cap exceeded")
    if int(report.get("epochs", -1)) > MAXIMUM_EPOCHS:
        raise NotebookContractError("epoch cap exceeded")
    if report.get("test_replay_bodies_read") != 0 or report.get("model_promoted") is not False or report.get("submission") is not False:
        raise NotebookContractError("training output expands forbidden scope")
    envelope = {
        "schema_version": 1,
        "record_id": "e01-production-recurrent-bc-notebook-execution-v2",
        "status": "PASS_NOTEBOOK_TRAINING_COMPLETED",
        "wrapper_sha256": wrapper_sha,
        "notebook_request_sha256": args.notebook_request_sha256,
        "training_request_sha256": TRAINING_REQUEST_SHA256,
        "approval_text_sha256": approval.get("approval_text_sha256"),
        "source_bundle_inventory_sha256": SOURCE_BUNDLE_INVENTORY_SHA256,
        "retained_inventory_sha256": RETAINED_INVENTORY_SHA256,
        "selected_replay_files": SELECTED_REPLAY_FILES,
        "selected_replay_bytes": SELECTED_REPLAY_BYTES,
        "optimizer_steps": int(report["optimizer_steps"]),
        "epochs": int(report["epochs"]),
        "test_replay_bodies_read": 0,
        "gpu": False,
        "tpu": False,
        "internet": False,
        "model_promoted": False,
        "submission": False,
        "output_inventory": output_inventory(output_dir),
        "wall_seconds": time.monotonic() - started,
    }
    envelope_path = output_dir / "notebook-execution-envelope.json"
    envelope_path.write_text(json.dumps(envelope, indent=2, sort_keys=True) + "\n")
    print(json.dumps(envelope, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()
